package com.shiptrack.contract.dto;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.shiptrack.contract.enums.EtaRisk;
import com.shiptrack.contract.enums.EventTimeType;
import com.shiptrack.contract.enums.EventType;

import java.time.OffsetDateTime;
import java.util.Map;

/**
 * Business event generated by the comparison engine.
 *
 * <p>Source: 接口文档_终稿.md §3.6</p>
 */
public record EventDto(
        @JsonProperty("id") long id,
        @JsonProperty("container_id") long containerId,
        @JsonProperty("notification_id") Long notificationId,
        @JsonProperty("event_key") String eventKey,
        @JsonProperty("event_type") EventType eventType,
        @JsonProperty("field_name") String fieldName,
        @JsonProperty("event_time_type") EventTimeType eventTimeType,
        @JsonProperty("from_snapshot_id") Long fromSnapshotId,
        @JsonProperty("to_snapshot_id") Long toSnapshotId,
        @JsonProperty("baseline_snapshot_id") Long baselineSnapshotId,
        @JsonProperty("baseline_delta") Map<String, Object> baselineDelta,
        @JsonProperty("risk_before") EtaRisk riskBefore,
        @JsonProperty("risk_after") EtaRisk riskAfter,
        @JsonProperty("old_value") Map<String, Object> oldValue,
        @JsonProperty("new_value") Map<String, Object> newValue,
        @JsonProperty("source_event_at") OffsetDateTime sourceEventAt,
        @JsonProperty("detected_at") OffsetDateTime detectedAt,
        @JsonProperty("source") String source
) {
}
